{
  "flashcards": [
    {
      "front": "How do you identify a slow PostgreSQL query?",
      "back": "Use EXPLAIN ANALYZE to inspect the execution plan, check pg_stat_statements for high-latency queries, and monitor locks or long-running transactions in pg_stat_activity.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the primary benefit of using database migrations?",
      "back": "Migrations provide version control for your database schema, ensuring consistent state across environments and allowing for safe, repeatable deployments.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you ensure transactional correctness in a distributed system?",
      "back": "Use ACID properties within the database, implement idempotency keys for API requests, and consider the Saga pattern or two-phase commits for cross-service consistency.",
      "requirement_ids": ["r3", "r4"]
    },
    {
      "front": "What is the main difference between REST and gRPC?",
      "back": "REST typically uses JSON over HTTP/1.1, making it human-readable and browser-friendly. gRPC uses Protocol Buffers over HTTP/2, offering binary serialization, strict typing, and high-performance streaming.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you handle breaking changes in a public API?",
      "back": "Use versioning (e.g., /v1/, /v2/), support deprecated endpoints for a transition period, and communicate changes clearly via documentation and deprecation headers.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is your strategy for mentoring junior engineers?",
      "back": "Focus on code reviews as teaching moments, pair programming on complex tasks, delegating ownership of small features, and encouraging them to ask 'why' rather than just 'how'.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What is the most critical component of an effective on-call rotation?",
      "back": "Actionable alerting. Alerts must be clear, prioritized, and accompanied by runbooks that provide immediate context and remediation steps to reduce MTTR.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the purpose of Terraform in infrastructure management?",
      "back": "Terraform provides Infrastructure as Code (IaC), allowing you to define, provision, and version control cloud resources predictably and repeatably.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is a common challenge when using Kubernetes for stateful services?",
      "back": "Managing persistent storage and data consistency during pod rescheduling or node failures requires careful configuration of PersistentVolumes and StatefulSets.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is the 'at-least-once' delivery guarantee in Kafka?",
      "back": "It ensures messages are never lost, but they might be delivered multiple times. Consumers must implement idempotency to handle potential duplicate messages safely.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "Why might you choose NATS over Kafka?",
      "back": "NATS is lightweight, easier to operate, and optimized for low-latency messaging, whereas Kafka is better suited for high-throughput, long-term event storage and replayability.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "What is the 'bullwhip effect' in supply chain management?",
      "back": "It is a phenomenon where small fluctuations in retail demand cause increasingly larger fluctuations in demand at the wholesale, distributor, and manufacturer levels.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "How do you handle Node.js event loop blocking?",
      "back": "Avoid heavy synchronous computations in the main thread. Offload CPU-intensive tasks to worker threads or move them to a background job queue.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the primary advantage of Go's concurrency model?",
      "back": "Goroutines are lightweight threads managed by the Go runtime, allowing thousands of concurrent operations with minimal memory overhead compared to OS threads.",
      "requirement_ids": ["r2"]
    }
  ]
}
